; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti89 (TI-89 / 92+ / V200 (68000, AMS)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_ti89_boot
; (the 68k backend requires this section be named ntc_md_vectors - the generic
;  "68k start" slot. On AMS there is no program-owned vector table; this is just
;  the entry. ;!!TI89? the real AMS nostub header/reloc goes here - stubbed.)
			bra ntc_ti89_boot

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; 2: Randomize 1234
			dc.l kw_seedl, 1234

			; 3: again:
lbl_again:

			; 4: t = Rnd(100) + 1 : tries = 0
			dc.l kw_rndl, 100, tmp0
			dc.l kw_addl, tmp0, 1, var_t
			dc.l kw_ztov, var_tries

			; 5: Print "I picked 1 to 100"
			dc.l kw_printstrvar, str0
			dc.l kw_printnl

			; 6: Do
do1_t:

			; 7: Input "Guess"; g
			dc.l kw_printstrvar, str1
			dc.l kw_inputint, var_g

			; 8: tries = tries + 1
			dc.l kw_inc, var_tries

			; 9: If g < t Then
			dc.l kw_scpltvv, var_g, var_t
			dc.l kw_goto_iffalse, if2_1

			; 10: Print "Higher"
			dc.l kw_printstrvar, str2
			dc.l kw_printnl

			; 11: ElseIf g > t Then
			dc.l if2_e_go
if2_1:
			dc.l kw_scpgtvv, var_g, var_t
			dc.l kw_goto_iffalse, if2_2

			; 12: Print "Lower"
			dc.l kw_printstrvar, str3
			dc.l kw_printnl

			; 13: End If
if2_2:
if2_e:

			; 14: Loop Until g = t
			dc.l kw_cpeqvv, var_g, var_t
			dc.l kw_goto_iffalse, do1_t
do1_e:

			; 15: Print "Got it in "; tries
			dc.l kw_printstrvar, str4
			dc.l kw_printint, var_tries
			dc.l kw_printnl

			; 16: Input "Again (y/n)"; a$
			dc.l kw_printstrvar, str5
			dc.l kw_inputstr, var_a

			; 17: If a$ = "y" Then GoTo again
			dc.l kw_strcmpeq, var_a, str6
			dc.l kw_goto_iftrue, lbl_again

			; 18: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str7
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if2_e_go:			lea if2_e, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; ============================================================
; Strings
; ============================================================

str0:			dc.b "I picked 1 to 100", 0
str1:			dc.b "Guess? ", 0
str2:			dc.b "Higher", 0
str3:			dc.b "Lower", 0
str4:			dc.b "Got it in ", 0
str5:			dc.b "Again (y/n)? ", 0
str6:			dc.b "y", 0
str7:			dc.b "Press a key", 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## ntc_d_inbuf @data

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_iftrue
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue:
			beq kw_git_go
			addq.l #4, sp
			rts
kw_git_go:
			movea.l (sp), sp
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_inc
kw_inc:
			movea.l (sp)+, a0
			addq.w #1, (a0)
			rts

			even
;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			add.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_div
; d0.w / d1.w signed, truncating: d0.w = quotient, d1.w = remainder (the
; dividend's sign). Divide by zero: quotient 0, remainder = dividend.
; -32768 / -1: quotient -32768, remainder 0 (as the Z80 library). jmp (a6)
ntc_div:
			tst.w d1
			beq ntc_div_z
			ext.l d0
			move.l d0, d2
			divs.w d1, d0
			bvs ntc_div_ov
			move.l d0, d1
			swap d1
			jmp (a6)
ntc_div_z:
			move.w d0, d1
			moveq #0, d0
			jmp (a6)
ntc_div_ov:
			move.w #$8000, d0
			moveq #0, d1
			jmp (a6)

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_scpltvv ntc_cmp
kw_scpltvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_slt

			even
;## kw_scpgtvv ntc_cmp
kw_scpgtvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sgt

			even
;## kw_cpeqvv
kw_cpeqvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			cmp.w (a1), d0
			rts

			even
;## ntc_rnd_seed

			even
;## kw_rndl ntc_rnd_seed ntc_div
;kw_rndl, <literal>, <destvar>
kw_rndl:
			move.l (sp)+, d1
ntc_rnd:
			move.w ntc_rnd_seed, d0		; h = high byte, l = low byte
			move.w d0, d2
			lsr.w #8, d2				; d2 = h
			moveq #0, d3
			move.b d0, d3				; d3 = l
			; h' = ((h & 1) << 7 | l >> 1) xor h
			move.b d2, d4
			andi.b #1, d4
			ror.b #1, d4
			move.b d3, d5
			lsr.b #1, d5
			or.b d5, d4
			eor.b d2, d4				; d4 = h'
			; l' = ((l & 1) << 7 | h' >> 1) xor l
			move.b d3, d5
			andi.b #1, d5
			ror.b #1, d5
			move.b d4, d6
			lsr.b #1, d6
			or.b d6, d5
			eor.b d3, d5				; d5 = l'
			eor.b d5, d4				; h'' = l' xor h'
			moveq #0, d0
			move.b d4, d0
			lsl.w #8, d0
			move.b d5, d0
			move.w d0, ntc_rnd_seed
			tst.w d1
			ble ntc_rnd_zero
			andi.w #$7FFF, d0
			lea kw_mod_rr, a6
			bra ntc_div
kw_mod_rr:
			movea.l (sp)+, a0
			move.w d1, (a0)
			rts
ntc_rnd_zero:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_seedl ntc_rnd_seed
;kw_seedl, <literal>
kw_seedl:
			move.l (sp)+, d0
			tst.w d0
			bne kw_sdl_ok
			moveq #1, d0
kw_sdl_ok:
			move.w d0, ntc_rnd_seed
			rts

; ============================================================
; Strings: 0 terminated. A string variable or temp has its capacity
; (1 .. 255 chars) in the byte before it: [cap][text...][0]. Array
; elements have no capacity byte (the caller gives the element size).
; ============================================================

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## ntc_gets ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and backspace, on the real stack (jsr). a2 = buffer (its
; capacity in the byte before it). 0 terminated, then a new line.
ntc_gets:
			moveq #0, d3
			move.b -1(a2), d3			; capacity
			moveq #0, d4				; typed
ntc_gs_wait:
			jsr ntc_plat_getkey
			cmpi.b #13, d0
			beq ntc_gs_done
			cmpi.b #127, d0
			beq ntc_gs_del
			cmpi.b #8, d0
			beq ntc_gs_del
			cmpi.b #32, d0
			bcs ntc_gs_wait
			cmp.w d3, d4
			bcc ntc_gs_wait
			move.b d0, 0(a2, d4.w)
			addq.w #1, d4
			jsr ntc_plat_putc
			bra ntc_gs_wait
ntc_gs_del:
			tst.w d4
			beq ntc_gs_wait
			subq.w #1, d4
			jsr ntc_plat_backspace
			bra ntc_gs_wait
ntc_gs_done:
			clr.b 0(a2, d4.w)
			jmp ntc_plat_newline

			even
;## kw_inputstr ntc_gets
;kw_inputstr, <straddr>
kw_inputstr:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_gets
			NTC_TS
			rts

			even
;## kw_inputint ntc_gets ntc_atoi ntc_d_inbuf
;kw_inputint, <var>  - signed decimal, stops at the first non digit
kw_inputint:
			move.l (sp)+, ntc_ivar
			lea ntc_inbuf, a2
			NTC_RS
			jsr ntc_gets
			NTC_TS
			lea ntc_inbuf, a0
			bra ntc_atoi

			even
;## ntc_atoi ntc_data
; text at a0 to a number into the var at (ntc_ivar). Spaces first, then - , then
; digits (or &H hex). Then rts (the thread).
ntc_atoi:
			moveq #0, d0				; value
			moveq #0, d2				; minus
ntc_at_sp:
			move.b (a0), d1
			cmpi.b #' ', d1
			bne ntc_at_sg
			addq.l #1, a0
			bra ntc_at_sp
ntc_at_sg:
			cmpi.b #'-', d1
			bne ntc_at_amp
			moveq #1, d2
			addq.l #1, a0
			move.b (a0), d1
ntc_at_amp:
			cmpi.b #'&', d1
			bne ntc_at_dec
			addq.l #1, a0
			move.b (a0)+, d1
			ori.b #$20, d1
			cmpi.b #'h', d1
			bne ntc_at_done
ntc_at_hex:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcs ntc_at_hd
			ori.b #$20, d1
			subi.b #'a'-'0', d1
			bcs ntc_at_done
			cmpi.b #6, d1
			bcc ntc_at_done
			addi.b #10, d1
ntc_at_hd:
			lsl.w #4, d0
			or.w d1, d0
			bra ntc_at_hex
ntc_at_dec:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcc ntc_at_done
			mulu.w #10, d0
			add.w d1, d0
			bra ntc_at_dec
ntc_at_done:
			tst.w d2
			beq ntc_at_st
			neg.w d0
ntc_at_st:
			movea.l ntc_ivar, a0
			move.w d0, (a0)
			rts

			even
;## ntc_ti89_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ti89_boot:
			; AMS entered us in user mode with a valid stack; clear the screen
			; and hand control to the thread (the compiler's start code follows,
			; sets A7 to the thread and runs).
			jsr ntc_ti89_clear
			rts

			even
;## ntc_plat_data ntc_data
; ------------------------------------------------------------
; UNVERIFIED hardware values - every one is a guess.  ;!!TI89? confirm all.
; ------------------------------------------------------------
LCD_MEM     equ $4C00           ; LCD bitmap base in RAM          ;!!TI89? guess
ROWBYTES    equ 30              ; bytes per pixel row (240/8; the 89 is 20) ;!!TI89?
SCRROWS     equ 128             ; pixel rows (the 89 is 100)       ;!!TI89?

ntc_curx:   dc.w 0              ; text column (0..cols-1)
ntc_cury:   dc.w 0              ; text row (0..rows-1)
ntc_frames: dc.w 0              ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; platform routines: entered with jsr, end with rts (real stack), keeping
; d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ti89_celladdr - a0 = LCD byte address of the top row of cell (curx,cury).
; addr = LCD_MEM + cury*8*ROWBYTES + curx   (8px-wide font = 1 byte per column)
ntc_ti89_celladdr:
			move.w ntc_cury, d1
			lsl.w #3, d1               ; row * 8 pixel rows
			mulu #ROWBYTES, d1
			add.w ntc_curx, d1
			lea LCD_MEM, a0
			adda.w d1, a0
			rts

; ntc_plat_putc - d0.b = character 32..127: blit its 8x8 glyph, advance
ntc_plat_putc:
			and.w #$00FF, d0
			sub.w #32, d0
			bge.s ntc_pc_ok
			moveq #0, d0               ; below space -> space
ntc_pc_ok:
			lsl.w #3, d0               ; glyph = font + char*8
			lea ntc_ti89_font, a1
			adda.w d0, a1
			jsr ntc_ti89_celladdr
			moveq #7, d2               ; 8 rows
ntc_pc_row:
			move.b (a1)+, (a0)
			adda.w #ROWBYTES, a0
			dbra d2, ntc_pc_row
			addq.w #1, ntc_curx
			cmp.w #30, ntc_curx        ; cols ;!!TI89? (89 = 20)
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - column 0, next row; scroll not done yet ;!!TI89? scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #16, ntc_cury        ; rows ;!!TI89? (89 = 12)
			blt.s ntc_nl_done
			move.w #15, ntc_cury
ntc_nl_done:
			rts

; ntc_ti89_clear - blank the whole LCD bitmap
ntc_ti89_clear:
			lea LCD_MEM, a0
			move.w #ROWBYTES*SCRROWS-1, d1
ntc_cl_lp:
			clr.b (a0)+
			dbra d1, ntc_cl_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_backspace @unit ntc_plat_screen ntc_plat_data ntc_data
ntc_plat_backspace:
			tst.w ntc_curx
			beq.s ntc_bs_done
			subq.w #1, ntc_curx
			jsr ntc_ti89_celladdr
			moveq #7, d2
ntc_bs_lp:
			clr.b (a0)
			adda.w #ROWBYTES, a0
			dbra d2, ntc_bs_lp
ntc_bs_done:
			rts

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0.  ;!!TI89? the 68k calc key matrix is a
; memory-mapped port read (row strobe / column read); the exact addresses were
; NOT grounded, so this is a stub returning "no key". Wire the port + a code
; map before Inkey works. (An AMS build would ROM_CALL ngetchx instead.)
ntc_plat_scankey:
			moveq #0, d0               ; ;!!TI89? no key matrix read yet
			rts

; ntc_plat_getkey - wait for a key (spins on the stub above until wired)
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - return to AMS. ;!!TI89? a nostub program returns with rts to
; the kernel; this restores nothing special yet.
ntc_plat_exit:
			rts


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_t:			dc.w 0
var_tries:			dc.w 0
var_g:			dc.w 0
			dc.b 40			; capacity
var_a:			ds.b 41
			even
tmp0:			dc.w 0
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
			dc.b 40					; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:	ds.b 41					; inputint: typed text
			even
			even
ntc_rnd_seed:	dc.w 1
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
